def decode_string(s: str) -> str:
    stack = []
    num = 0
    result = ""

    for char in s:
        if char.isdigit():
            num = num * 10 + int(char)
        elif char == '[':
            stack.append((result, num))
            result = ""
            num = 0
        elif char == ']':
            prev_result, k = stack.pop()
            result = prev_result + result * k
        else:
            result += char

    return result
